+    background: rgba(255,255,255,0.05); }
+
+  .hud { position: fixed; left: 18px; bottom: 16px; background: var(--panel); border: 1px solid var(--panel-border);
+    border-radius: 14px; padding: 12px 14px; backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
+    box-shadow: 0 14px 40px rgba(0,0,0,0.45); min-width: 380px; }
