+  .pill { font-size: 11px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; padding: 3px 9px;
+    border-radius: 999px; background: rgba(255,255,255,0.08); color: var(--muted); }
+  .pill.running { background: rgba(255,122,47,0.2); color: var(--accent-2); }
+  .pill.settled { background: rgba(76,217,123,0.16); color: var(--ok); }
+  .hud-grid { display: grid; grid-template-columns: repeat(4, minmax(80px, 1fr)); gap: 8px 16px; margin: 0; }
+  .hud-grid dt { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: 0.5px; }
+  .hud-grid dd { margin: 1px 0 0; font-family: var(--mono); font-size: 14px; }
+  .hud-grid dd small { color: var(--muted); font-size: 11px; }
+  .bar { height: 5px; border-radius: 3px; background: rgba(255,255,255,0.08); overflow: hidden; margin-top: 8px; }
+  .bar > i { display: block; height: 100%; background: linear-gradient(90deg, var(--accent), var(--accent-2)); width: 0%; transition: width .2s; }
+
+  @media (max-width: 900px) {
+    .panel { width: 280px; }
+    .hud { min-width: 0; right: 16px; }
+    .hud-grid { grid-template-columns: repeat(2, 1fr); }
+  }
+</style>
+</head>
+<body>
+<canvas id="scene"></canvas>
+
+<header class="brand">
+  <h1>Claude Fable 5.1</h1>
+  <p>Brick wall crash lab · deterministic 2D rigid-body sandbox</p>
+</header>
+
+<aside class="panel" id="panel">
+  <div class="panel-head">
+    <button id="btnTest" class="btn primary" title="Run the crash test (Space)">Test</button>
+    <button id="btnReset" class="btn" title="Rebuild the scene (R)">Reset</button>
+    <button id="btnSettings" class="btn ghost" title="Toggle settings">Settings</button>
+  </div>
+  <div class="active-values" id="activeValues"></div>
+  <div class="settings" id="settings">
+    <div class="group" id="mainParams"></div>
+    <details class="group" id="advWrap">
+      <summary>Advanced physics</summary>
+      <div id="advParams"></div>
+    </details>
+    <div class="row-actions">
+      <button id="btnDefaults" class="btn small">Restore defaults</button>
+      <span class="note" id="pendingNote"></span>
+    </div>
+    <p class="hint">Depth layers are simulated as independent brick planes stacked behind each other; the car must push all of them. <kbd>Space</kbd> test · <kbd>R</kbd> reset.</p>
+  </div>
+</aside>
+
+<section class="hud">
+  <div class="hud-state">
+    <span id="statePill" class="pill">Ready</span>
+    <span id="stateText" style="color: var(--muted); font-size: 12px;">Press Test to launch the car.</span>
+  </div>
+  <dl class="hud-grid">
+    <div><dt>Car speed</dt><dd><span id="tSpeed">0.0</span> m/s <small id="tKmh"></small></dd></div>
+    <div><dt>Elapsed</dt><dd><span id="tTime">0.00</span> s</dd></div>
+    <div><dt>Moving bricks</dt><dd><span id="tMoving">0</span><small> / <span id="tTotal">0</span></small></dd></div>
+    <div><dt>Wall displaced</dt><dd><span id="tDisplaced">0</span>%</dd></div>
+    <div><dt>Impact speed</dt><dd id="tImpact">–</dd></div>
+    <div><dt>Peak decel</dt><dd id="tDecel">–</dd></div>
+    <div><dt>Car energy</dt><dd id="tKE">–</dd></div>
+    <div><dt>Solver</dt><dd id="tSolver" style="font-size: 11px;"></dd></div>
+  </dl>
+  <div class="bar"><i id="energyBar"></i></div>
+</section>
+
+<script>
+(() => {
+'use strict';
+
+/* =====================================================================
+   Parameters
+   ===================================================================== */
+const DEFAULTS = {
+  carSpeed: 22, cols: 12, rows: 8, layers: 2, brickMass: 2.5,
+  brickW: 0.5, brickH: 0.24, gravity: 9.81, brickFriction: 0.72, brickRestitution: 0.18,
+  carMass: 1250, carW: 4.2, carH: 1.45, groundFriction: 0.85, scale: 80,
+};
+const PARAM_DEFS = [
+  { key: 'carSpeed', label: 'Car speed', unit: 'm/s', min: 5, max: 45, step: 0.5, group: 'main' },
+  { key: 'cols', label: 'Wall columns', unit: 'bricks wide', min: 4, max: 24, step: 1, group: 'main' },
+  { key: 'rows', label: 'Wall rows', unit: 'bricks tall', min: 3, max: 16, step: 1, group: 'main' },
+  { key: 'layers', label: 'Wall depth layers', unit: 'layers', min: 1, max: 5, step: 1, group: 'main' },
+  { key: 'brickMass', label: 'Brick mass', unit: 'kg / brick', min: 0.5, max: 12, step: 0.1, group: 'main' },
+  { key: 'brickW', label: 'Brick width', unit: 'm', min: 0.2, max: 1, step: 0.01, group: 'adv' },
+  { key: 'brickH', label: 'Brick height', unit: 'm', min: 0.1, max: 0.5, step: 0.01, group: 'adv' },
+  { key: 'gravity', label: 'Gravity', unit: 'm/s²', min: 1, max: 25, step: 0.01, group: 'adv' },
+  { key: 'brickFriction', label: 'Brick friction', unit: 'μ', min: 0, max: 1.5, step: 0.01, group: 'adv' },
+  { key: 'brickRestitution', label: 'Brick restitution', unit: 'e', min: 0, max: 0.8, step: 0.01, group: 'adv' },
+  { key: 'carMass', label: 'Car mass', unit: 'kg', min: 300, max: 4000, step: 10, group: 'adv' },
+  { key: 'carW', label: 'Car width', unit: 'm', min: 2.5, max: 6, step: 0.05, group: 'adv' },
+  { key: 'carH', label: 'Car height', unit: 'm', min: 0.9, max: 2.5, step: 0.05, group: 'adv' },
+  { key: 'groundFriction', label: 'Ground friction', unit: 'μ', min: 0, max: 1.5, step: 0.01, group: 'adv' },
+  { key: 'scale', label: 'Simulation scale', unit: 'px / m', min: 30, max: 140, step: 1, group: 'adv' },
+];
+const settings = { ...DEFAULTS };
+
+/* =====================================================================
+   Solver constants
+   ===================================================================== */
+const ALLOWED_PENETRATION = 0.005;
+const BIAS_FACTOR = 0.2;
+const RESTITUTION_VEL = 1.0;
+const SLEEP_LIN = 0.06, SLEEP_ANG = 0.15, SLEEP_TIME = 0.6;
+const MAX_LAUNCH_ACCEL = 30;
+const COAST_DIST = 1.0;
+const MIN_RUNUP = 3.0;
+
+/* =====================================================================
+   Rigid body
+   ===================================================================== */
+let nextBodyId = 0;
+class Body {
+  constructor(hw, hh, mass) {
+    this.id = nextBodyId++;
+    this.hw = hw; this.hh = hh;
+    this.x = 0; this.y = 0; this.a = 0;
+    this.vx = 0; this.vy = 0; this.w = 0;
+    this.fx = 0; this.fy = 0; this.torque = 0;
+    this.cos = 1; this.sin = 0;
+    this.minX = 0; this.maxX = 0; this.minY = 0; this.maxY = 0;
+    this.friction = 0.7; this.restitution = 0;
+    this.layer = -1; this.kind = 'brick'; this.index = 0;
+    this.isStatic = !isFinite(mass);
+    if (this.isStatic) { this.mass = Infinity; this.invMass = 0; this.I = Infinity; this.invI = 0; }
+    else { this.mass = mass; this.invMass = 1 / mass; this.I = mass * (4 * hw * hw + 4 * hh * hh) / 12; this.invI = 1 / this.I; }
+    this.asleep = false; this.sleepTime = 0; this.canSleep = true;
+    this.touching = [];
+    this.cx0 = 0; this.cx1 = 0; this.cy0 = 0; this.cy1 = 0;
+    this.x0 = 0; this.y0 = 0;
+  }
+  updateTransform() {
+    const c = Math.cos(this.a), s = Math.sin(this.a);
+    this.cos = c; this.sin = s;
+    const ex = Math.abs(c) * this.hw + Math.abs(s) * this.hh;
+    const ey = Math.abs(s) * this.hw + Math.abs(c) * this.hh;
+    this.minX = this.x - ex; this.maxX = this.x + ex;
+    this.minY = this.y - ey; this.maxY = this.y + ey;
+  }
+  get inactive() { return this.asleep || this.isStatic; }
+}
+
+/* =====================================================================
+   Box-box contact generation (SAT + reference-face clipping)
+   ===================================================================== */
+const E1 = 1, E2 = 2, E3 = 3, E4 = 4;
+// feature packing: inEdge1 | outEdge1<<8 | inEdge2<<16 | outEdge2<<24
+const fpFlip = f => ((f & 0xFFFF) << 16) | ((f >>> 16) & 0xFFFF);
+class Contact {
+  constructor() {
+    this.px = 0; this.py = 0; this.nx = 0; this.ny = 0; this.separation = 0; this.feature = 0;
+    this.Pn = 0; this.Pt = 0; this.massNormal = 0; this.massTangent = 0; this.bias = 0; this.velBias = 0;
+    this.r1x = 0; this.r1y = 0; this.r2x = 0; this.r2y = 0;
+  }
+}
+const mkClip = () => ({ x: 0, y: 0, fp: 0 });
+const incident = [mkClip(), mkClip()], clip1 = [mkClip(), mkClip()], clip2 = [mkClip(), mkClip()];
+
+function computeIncidentEdge(c, hx, hy, body, nx, ny) {
+  const co = body.cos, si = body.sin;
+  const nlx = -(co * nx + si * ny), nly = -(-si * nx + co * ny);
+  let v0x, v0y, v1x, v1y, in0, out0, in1, out1;
+  if (Math.abs(nlx) > Math.abs(nly)) {
+    if (nlx > 0) { v0x = hx; v0y = -hy; in0 = E3; out0 = E4; v1x = hx; v1y = hy; in1 = E4; out1 = E1; }
+    else { v0x = -hx; v0y = hy; in0 = E1; out0 = E2; v1x = -hx; v1y = -hy; in1 = E2; out1 = E3; }
+  } else {
+    if (nly > 0) { v0x = hx; v0y = hy; in0 = E4; out0 = E1; v1x = -hx; v1y = hy; in1 = E1; out1 = E2; }
+    else { v0x = -hx; v0y = -hy; in0 = E2; out0 = E3; v1x = hx; v1y = -hy; in1 = E3; out1 = E4; }
+  }
+  c[0].x = body.x + co * v0x - si * v0y; c[0].y = body.y + si * v0x + co * v0y; c[0].fp = (in0 << 16) | (out0 << 24);
+  c[1].x = body.x + co * v1x - si * v1y; c[1].y = body.y + si * v1x + co * v1y; c[1].fp = (in1 << 16) | (out1 << 24);
+}
+
+function clipSegmentToLine(vOut, vIn, nx, ny, offset, clipEdge) {
+  let n = 0;
+  const d0 = nx * vIn[0].x + ny * vIn[0].y - offset;
+  const d1 = nx * vIn[1].x + ny * vIn[1].y - offset;
+  if (d0 <= 0) { vOut[n].x = vIn[0].x; vOut[n].y = vIn[0].y; vOut[n].fp = vIn[0].fp; n++; }
+  if (d1 <= 0) { vOut[n].x = vIn[1].x; vOut[n].y = vIn[1].y; vOut[n].fp = vIn[1].fp; n++; }
+  if (d0 * d1 < 0) {
+    const t = d0 / (d0 - d1);
+    const o = vOut[n];
+    o.x = vIn[0].x + t * (vIn[1].x - vIn[0].x);
+    o.y = vIn[0].y + t * (vIn[1].y - vIn[0].y);
+    if (d0 > 0) o.fp = (vIn[0].fp & 0xFF00FF00) | clipEdge;          // inEdge1 = clipEdge, inEdge2 = none
+    else o.fp = (vIn[1].fp & 0x00FF00FF) | (clipEdge << 8);          // outEdge1 = clipEdge, outEdge2 = none
+    n++;
+  }
+  return n;
+}
+
+function collide(A, B, out) {
+  const hAx = A.hw, hAy = A.hh, hBx = B.hw, hBy = B.hh;
+  const ca = A.cos, sa = A.sin, cb = B.cos, sb = B.sin;
+  const dpx = B.x - A.x, dpy = B.y - A.y;
+  const dAx = ca * dpx + sa * dpy, dAy = -sa * dpx + ca * dpy;
+  const dBx = cb * dpx + sb * dpy, dBy = -sb * dpx + cb * dpy;
+  const C11 = ca * cb + sa * sb, C21 = ca * sb - sa * cb;
+  const aC = Math.abs(C11), aS = Math.abs(C21);
+
+  const faceAx = Math.abs(dAx) - hAx - (aC * hBx + aS * hBy);
+  const faceAy = Math.abs(dAy) - hAy - (aS * hBx + aC * hBy);
+  if (faceAx > 0 || faceAy > 0) return 0;
+  const faceBx = Math.abs(dBx) - (aC * hAx + aS * hAy) - hBx;
+  const faceBy = Math.abs(dBy) - (aS * hAx + aC * hAy) - hBy;
+  if (faceBx > 0 || faceBy > 0) return 0;
+
+  let axis = 0, sep = faceAx, nx, ny;
+  if (dAx > 0) { nx = ca; ny = sa; } else { nx = -ca; ny = -sa; }
+  const relTol = 0.95, absTol = 0.01;
+  if (faceAy > relTol * sep + absTol * hAy) { axis = 1; sep = faceAy; if (dAy > 0) { nx = -sa; ny = ca; } else { nx = sa; ny = -ca; } }
+  if (faceBx > relTol * sep + absTol * hBx) { axis = 2; sep = faceBx; if (dBx > 0) { nx = cb; ny = sb; } else { nx = -cb; ny = -sb; } }
+  if (faceBy > relTol * sep + absTol * hBy) { axis = 3; sep = faceBy; if (dBy > 0) { nx = -sb; ny = cb; } else { nx = sb; ny = -cb; } }
+
+  let fnx, fny, front, snx, sny, side, negSide, posSide, negEdge, posEdge;
+  switch (axis) {
+    case 0:
+      fnx = nx; fny = ny; front = A.x * fnx + A.y * fny + hAx;
+      snx = -sa; sny = ca; side = A.x * snx + A.y * sny;
+      negSide = -side + hAy; posSide = side + hAy; negEdge = E3; posEdge = E1;
+      computeIncidentEdge(incident, hBx, hBy, B, fnx, fny); break;
+    case 1:
+      fnx = nx; fny = ny; front = A.x * fnx + A.y * fny + hAy;
+      snx = ca; sny = sa; side = A.x * snx + A.y * sny;
+      negSide = -side + hAx; posSide = side + hAx; negEdge = E2; posEdge = E4;
+      computeIncidentEdge(incident, hBx, hBy, B, fnx, fny); break;
+    case 2:
+      fnx = -nx; fny = -ny; front = B.x * fnx + B.y * fny + hBx;
+      snx = -sb; sny = cb; side = B.x * snx + B.y * sny;
+      negSide = -side + hBy; posSide = side + hBy; negEdge = E3; posEdge = E1;
+      computeIncidentEdge(incident, hAx, hAy, A, fnx, fny); break;
+    default:
+      fnx = -nx; fny = -ny; front = B.x * fnx + B.y * fny + hBy;
+      snx = cb; sny = sb; side = B.x * snx + B.y * sny;
+      negSide = -side + hBx; posSide = side + hBx; negEdge = E2; posEdge = E4;
+      computeIncidentEdge(incident, hAx, hAy, A, fnx, fny); break;
+  }
+  if (clipSegmentToLine(clip1, incident, -snx, -sny, negSide, negEdge) < 2) return 0;
+  if (clipSegmentToLine(clip2, clip1, snx, sny, posSide, posEdge) < 2) return 0;
+
+  let n = 0;
+  for (let i = 0; i < 2; i++) {
+    const s = fnx * clip2[i].x + fny * clip2[i].y - front;
+    if (s <= 0) {
+      const c = out[n++];
+      c.separation = s; c.nx = nx; c.ny = ny;
+      c.px = clip2[i].x - s * fnx; c.py = clip2[i].y - s * fny;
+      c.feature = axis >= 2 ? fpFlip(clip2[i].fp) : clip2[i].fp;
+    }
+  }
+  return n;
+}
+
+/* =====================================================================
+   Persistent contact arbiter (sequential impulses, warm started)
+   ===================================================================== */
+class Arbiter {
+  constructor(a, b) {
+    this.a = a; this.b = b;
+    this.contacts = [new Contact(), new Contact()];
+    this.spare = [new Contact(), new Contact()];
+    this.n = 0; this.stamp = 0;
+    this.friction = 0; this.restitution = 0;
+    this.im1 = 0; this.iI1 = 0; this.im2 = 0; this.iI2 = 0;
+  }
+  update(newC, n) {
+    const spare = this.spare, old = this.contacts;
+    for (let i = 0; i < n; i++) {
+      const nc = newC[i], s = spare[i];
+      s.px = nc.px; s.py = nc.py; s.nx = nc.nx; s.ny = nc.ny; s.separation = nc.separation; s.feature = nc.feature;
+      s.Pn = 0; s.Pt = 0;
+      for (let j = 0; j < this.n; j++) {
+        if (old[j].feature === nc.feature) { s.Pn = old[j].Pn; s.Pt = old[j].Pt; break; }
+      }
+    }
+    this.spare = old; this.contacts = spare; this.n = n;
+    this.friction = Math.sqrt(this.a.friction * this.b.friction);
+    this.restitution = Math.max(this.a.restitution, this.b.restitution);
