+
+/* =====================================================================
+   Rendering
+   ===================================================================== */
+function resize() {
+  dpr = Math.min(2, window.devicePixelRatio || 1);
+  W = window.innerWidth; H = window.innerHeight;
+  canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr);
+  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
+}
+
+function render() {
+  const scale = scene.params.scale;
+  const groundY = Math.round(H * 0.78) + camera.shakeY;
+  const camX = camera.x - camera.shakeX / scale;
+  const sx = wx => (wx - camX) * scale;
+  const sy = wy => groundY - wy * scale;
+
+  // sky
+  const sky = ctx.createLinearGradient(0, 0, 0, groundY);
+  sky.addColorStop(0, '#0d1420'); sky.addColorStop(0.55, '#1c2a3f'); sky.addColorStop(1, '#3b4a5e');
+  ctx.fillStyle = sky; ctx.fillRect(0, 0, W, H);
+
+  // distant facility silhouettes (parallax)
+  ctx.fillStyle = '#16202e';
+  const par = 0.25, spacing = 9;
+  const firstK = Math.floor((camX * par - 10) / spacing);
+  for (let k = firstK; k < firstK + Math.ceil(W / scale / spacing) + 5; k++) {
+    const h0 = 1.4 + ((k * 7919) % 5) * 0.55, w0 = 5.5 + ((k * 104729) % 4) * 0.8;
+    const bx = (k * spacing - camX * par) * scale;
+    ctx.fillRect(bx, groundY - h0 * scale, w0 * scale, h0 * scale);
+    if (k % 3 === 0) ctx.fillRect(bx + w0 * scale * 0.7, groundY - (h0 + 1.6) * scale, 0.25 * scale, 1.6 * scale);
+  }
+  // horizon glow
+  const glow = ctx.createLinearGradient(0, groundY - 60, 0, groundY);
+  glow.addColorStop(0, 'rgba(255,170,100,0)'); glow.addColorStop(1, 'rgba(255,170,100,0.12)');
+  ctx.fillStyle = glow; ctx.fillRect(0, groundY - 60, W, 60);
+
+  // ground
+  const gnd = ctx.createLinearGradient(0, groundY, 0, H);
+  gnd.addColorStop(0, '#3a3d43'); gnd.addColorStop(0.06, '#2b2e33'); gnd.addColorStop(1, '#15171b');
+  ctx.fillStyle = gnd; ctx.fillRect(0, groundY, W, H - groundY);
+  ctx.fillStyle = '#a8adb5'; ctx.fillRect(0, groundY - 2, W, 2);
+
+  // distance ticks
+  const x0m = Math.floor(camX), x1m = Math.ceil(camX + W / scale);
+  ctx.textAlign = 'center'; ctx.font = '11px ui-monospace, Menlo, monospace';
+  for (let m = x0m; m <= x1m; m++) {
+    const px = sx(m);
+    const major = m % 5 === 0;
+    ctx.fillStyle = major ? 'rgba(255,255,255,0.55)' : 'rgba(255,255,255,0.22)';
+    ctx.fillRect(px - 0.5, groundY + 4, 1, major ? 14 : 7);
+    if (major) { ctx.fillText(`${m > 0 ? '+' : ''}${m} m`, px, groundY + 32); }
+  }
+  // impact line
+  ctx.strokeStyle = 'rgba(255,180,90,0.35)'; ctx.setLineDash([6, 8]); ctx.lineWidth = 1;
+  ctx.beginPath(); ctx.moveTo(sx(0), groundY); ctx.lineTo(sx(0), groundY - Math.max(scene.wallH + 1.2, 3) * scale); ctx.stroke();
+  ctx.setLineDash([]);
+  ctx.fillStyle = 'rgba(255,180,90,0.7)'; ctx.textAlign = 'left'; ctx.font = '11px system-ui, sans-serif';
+  ctx.fillText('wall face', sx(0) + 6, groundY - Math.max(scene.wallH + 1.2, 3) * scale + 12);
+
+  // skid marks
+  ctx.strokeStyle = 'rgba(15,15,18,0.55)'; ctx.lineWidth = Math.max(2, 0.16 * scale); ctx.lineCap = 'round';
+  for (const arr of skids) {
+    if (arr.length < 2) continue;
+    ctx.beginPath(); ctx.moveTo(sx(arr[0]), groundY - 1);
+    for (let i = 1; i < arr.length; i++) ctx.lineTo(sx(arr[i]), groundY - 1);
+    ctx.stroke();
+  }
+
+  drawBricks(sx, sy, scale);
+  drawCar(sx, sy, scale, groundY);
+  drawParticles(sx, sy, scale);
+}
+
+const cornerX = new Float64Array(4), cornerY = new Float64Array(4);
+function bodyCorners(b, sx, sy, ox, oy) {
+  const c = b.cos, s = b.sin, hw = b.hw, hh = b.hh;
+  const ax = c * hw, ay = s * hw, bx = -s * hh, by = c * hh;
+  cornerX[0] = sx(b.x - ax - bx) + ox; cornerY[0] = sy(b.y - ay - by) + oy;
+  cornerX[1] = sx(b.x + ax - bx) + ox; cornerY[1] = sy(b.y + ay - by) + oy;
+  cornerX[2] = sx(b.x + ax + bx) + ox; cornerY[2] = sy(b.y + ay + by) + oy;
+  cornerX[3] = sx(b.x - ax + bx) + ox; cornerY[3] = sy(b.y - ay + by) + oy;
+}
+
+function drawBricks(sx, sy, scale) {
+  const layers = scene.params.layers;
+  const depth = 0.12 * scale;
+  const ex = depth * 0.7, ey = -depth * 0.5;
+  const vwPad = 2 * scale;
+  for (let k = layers - 1; k >= 0; k--) {
+    const ox = k * ex, oy = k * ey;
+    for (const b of scene.world.bricks) {
+      if (b.layer !== k) continue;
+      const bxs = sx(b.x);
+      if (bxs < -vwPad || bxs > W + vwPad) continue;
+      bodyCorners(b, sx, sy, ox, oy);
+      // extruded faces facing the depth vector
+      for (let i = 0; i < 4; i++) {
+        const j = (i + 1) & 3;
+        const dx = cornerX[j] - cornerX[i], dy = cornerY[j] - cornerY[i];
+        const nx = -dy, ny = dx;
+        const d = nx * ex + ny * ey;
+        if (d <= 0) continue;
+        const len = Math.hypot(nx, ny) || 1;
+        ctx.fillStyle = (-ny / len) > 0.5 ? b.topCol : b.sideCol;
+        ctx.beginPath();
+        ctx.moveTo(cornerX[i], cornerY[i]); ctx.lineTo(cornerX[j], cornerY[j]);
+        ctx.lineTo(cornerX[j] + ex, cornerY[j] + ey); ctx.lineTo(cornerX[i] + ex, cornerY[i] + ey);
+        ctx.closePath(); ctx.fill();
+      }
+      ctx.fillStyle = b.faceCol;
+      ctx.beginPath();
+      ctx.moveTo(cornerX[0], cornerY[0]); ctx.lineTo(cornerX[1], cornerY[1]);
+      ctx.lineTo(cornerX[2], cornerY[2]); ctx.lineTo(cornerX[3], cornerY[3]); ctx.closePath();
+      ctx.fill();
+      ctx.strokeStyle = 'rgba(30,18,14,0.75)'; ctx.lineWidth = 1; ctx.stroke();
+    }
+  }
+}
+
+function drawCar(sx, sy, scale, groundY) {
+  const car = scene.car, hw = car.hw, hh = car.hh;
+  const crush = impacted ? Math.min(0.16, Math.max(0, (impactSpeed - Math.abs(car.vx)) / 45) * 0.16 + Math.min(0.06, peakDecelG / 600)) : 0;
+  const cx = sx(car.x), cy = sy(car.y);
+  // shadow
+  ctx.fillStyle = 'rgba(0,0,0,0.35)';
+  ctx.beginPath(); ctx.ellipse(cx, groundY + 2, hw * scale * 0.95, 0.1 * scale, 0, 0, Math.PI * 2); ctx.fill();
+
+  ctx.save();
+  ctx.translate(cx, cy); ctx.rotate(-car.a); ctx.scale(scale, -scale);
+  const r = Math.min(0.34, hh * 0.5);
+  const yB = -hh + hh * 1.05; // beltline
+  const fx = x => x > 0 ? x * (1 - crush) : x;
+  // body
+  ctx.beginPath();
+  ctx.moveTo(-hw, -hh + r * 0.7);
+  ctx.lineTo(-hw, yB - 0.08);
+  ctx.lineTo(-hw + 0.25, yB);
+  ctx.lineTo(-hw * 0.5, yB);
+  ctx.lineTo(-hw * 0.22, hh);
+  ctx.lineTo(fx(hw * 0.14), hh);
+  ctx.lineTo(fx(hw * 0.5), yB);
+  ctx.lineTo(fx(hw - 0.2), yB - 0.04);
+  ctx.lineTo(fx(hw), yB - 0.32);
+  ctx.lineTo(fx(hw), -hh + r * 0.7);
+  ctx.closePath();
+  const bodyGrad = ctx.createLinearGradient(0, -hh, 0, hh);
+  bodyGrad.addColorStop(0, '#c8ccd3'); bodyGrad.addColorStop(0.5, '#f1f3f6'); bodyGrad.addColorStop(1, '#ffffff');
+  ctx.fillStyle = bodyGrad; ctx.fill();
+  ctx.lineWidth = 0.025; ctx.strokeStyle = '#3b4149'; ctx.stroke();
+  // windows
+  ctx.fillStyle = '#1f2b3a';
+  ctx.beginPath();
+  ctx.moveTo(-hw * 0.46, yB + 0.03); ctx.lineTo(-hw * 0.2, hh - 0.07);
+  ctx.lineTo(fx(hw * 0.12), hh - 0.07); ctx.lineTo(fx(hw * 0.44), yB + 0.03); ctx.closePath(); ctx.fill();
+  ctx.strokeStyle = '#e6e9ee'; ctx.lineWidth = 0.03;
+  ctx.beginPath(); ctx.moveTo(-hw * 0.04, yB + 0.03); ctx.lineTo(-hw * 0.04, hh - 0.07); ctx.stroke();
+  // stripe
+  ctx.fillStyle = '#ff7a2f';
+  ctx.fillRect(-hw + 0.05, yB - 0.33, fx(hw) + hw - 0.15, 0.09);
+  // crash-test target
+  const tx = -hw * 0.05, ty = -hh + r * 0.7 + (yB - (-hh + r * 0.7)) * 0.42, tr = Math.min(0.17, hh * 0.22);
+  for (let q = 0; q < 4; q++) {
+    ctx.fillStyle = q % 2 ? '#111' : '#ffd23f';
+    ctx.beginPath(); ctx.moveTo(tx, ty); ctx.arc(tx, ty, tr, q * Math.PI / 2, (q + 1) * Math.PI / 2); ctx.closePath(); ctx.fill();
+  }
+  // lights
+  ctx.fillStyle = '#ffe9a6'; ctx.fillRect(fx(hw) - 0.16, yB - 0.3, 0.14, 0.12);
+  ctx.fillStyle = '#e0342a'; ctx.fillRect(-hw + 0.02, yB - 0.3, 0.12, 0.12);
+  // wheels
+  for (const wxl of [-hw * 0.6, hw * 0.6]) {
+    const wx = wxl > 0 ? fx(wxl) : wxl, wy = -hh + r;
+    ctx.fillStyle = '#15171a'; ctx.beginPath(); ctx.arc(wx, wy, r, 0, Math.PI * 2); ctx.fill();
+    ctx.fillStyle = '#9aa1ab'; ctx.beginPath(); ctx.arc(wx, wy, r * 0.58, 0, Math.PI * 2); ctx.fill();
+    ctx.strokeStyle = '#4a5058'; ctx.lineWidth = 0.03;
+    const spin = car.x / r;
+    for (let s = 0; s < 5; s++) {
+      const ang = spin + s * Math.PI * 2 / 5;
+      ctx.beginPath(); ctx.moveTo(wx, wy); ctx.lineTo(wx + Math.cos(ang) * r * 0.5, wy + Math.sin(ang) * r * 0.5); ctx.stroke();
+    }
+    ctx.fillStyle = '#2a2e34'; ctx.beginPath(); ctx.arc(wx, wy, r * 0.14, 0, Math.PI * 2); ctx.fill();
+  }
+  ctx.restore();
+}
+
+function drawParticles(sx, sy, scale) {
+  for (const p of particles) {
+    const t = p.life / p.maxLife, alpha = (1 - t) * 0.55;
+    const g = Math.round(150 + p.warm * 40), rch = Math.round(160 + p.warm * 60), b = Math.round(135 + (1 - p.warm) * 30);
+    ctx.fillStyle = `rgba(${rch},${g},${b},${alpha.toFixed(3)})`;
+    ctx.beginPath(); ctx.arc(sx(p.x), sy(p.y), p.r * scale, 0, Math.PI * 2); ctx.fill();
+  }
+}
+
+/* =====================================================================
+   UI
+   ===================================================================== */
+const $ = id => document.getElementById(id);
+const fmt = (v, d = 1) => Number(v).toFixed(d);
+
+function buildControls() {
+  const main = $('mainParams'), adv = $('advParams');
+  for (const def of PARAM_DEFS) {
+    const row = document.createElement('div'); row.className = 'param';
+    row.innerHTML = `<label for="num-${def.key}"><span>${def.label}</span><small>${def.unit}</small></label>
+      <input type="number" id="num-${def.key}" min="${def.min}" max="${def.max}" step="${def.step}">
+      <input type="range" id="rng-${def.key}" min="${def.min}" max="${def.max}" step="${def.step}">`;
+    (def.group === 'main' ? main : adv).appendChild(row);
+    const num = row.querySelector('input[type=number]'), rng = row.querySelector('input[type=range]');
+    num.value = settings[def.key]; rng.value = settings[def.key];
+    const onChange = (raw, commit) => {
+      let v = parseFloat(raw);
+      if (!isFinite(v)) return;
+      if (commit) v = Math.min(def.max, Math.max(def.min, v));
+      settings[def.key] = v;
+      if (commit) { num.value = v; }
+      rng.value = v;
+      onSettingsChanged();
+    };
+    rng.addEventListener('input', () => { onChange(rng.value, true); });
+    num.addEventListener('input', () => onChange(num.value, false));
+    num.addEventListener('change', () => onChange(num.value, true));
+    def.num = num; def.rng = rng;
+  }
+}
+
+function syncControls() {
+  for (const def of PARAM_DEFS) { def.num.value = settings[def.key]; def.rng.value = settings[def.key]; }
+}
+
+function onSettingsChanged() {
+  if (state === 'ready') resetScene();
+  else { pendingChanges = true; updatePendingNote(); }
+}
+
+function updatePendingNote() {
+  $('pendingNote').textContent = pendingChanges ? 'Changes apply on next Test / Reset' : '';
+}
+
+function renderActiveValues() {
+  const p = scene.params;
+  $('activeValues').innerHTML = `Active run
+    <div class="chips">
+      <span class="chip"><b>${fmt(p.carSpeed, 1)}</b> m/s</span>
+      <span class="chip"><b>${p.cols}×${p.rows}</b> bricks</span>
+      <span class="chip"><b>${p.layers}</b> layer${p.layers > 1 ? 's' : ''}</span>
+      <span class="chip"><b>${fmt(p.brickMass, 2)}</b> kg/brick</span>
+      <span class="chip"><b>${fmt(p.brickW, 2)}×${fmt(p.brickH, 2)}</b> m</span>
+      <span class="chip">g <b>${fmt(p.gravity, 2)}</b></span>
+      <span class="chip">μ <b>${fmt(p.brickFriction, 2)}</b> · e <b>${fmt(p.brickRestitution, 2)}</b></span>
+      <span class="chip">car <b>${p.carMass}</b> kg · <b>${fmt(p.carW, 2)}×${fmt(p.carH, 2)}</b> m</span>
+      <span class="chip">ground μ <b>${fmt(p.groundFriction, 2)}</b></span>
+      <span class="chip"><b>${p.scale}</b> px/m</span>
+      <span class="chip">launch <b>${fmt(scene.launchAccel, 1)}</b> m/s² over <b>${fmt(scene.runup, 1)}</b> m</span>
+    </div>`;
+}
+
+function updateHud() {
+  const car = scene.car, world = scene.world;
+  const speed = Math.hypot(car.vx, car.vy);
+  $('tSpeed').textContent = fmt(speed, 1);
+  $('tKmh').textContent = `${fmt(speed * 3.6, 0)} km/h`;
+  $('tTime').textContent = fmt(simTime, 2);
+  let moving = 0, displaced = 0, awake = 0;
+  for (const b of world.bricks) {
+    if (!b.asleep) { awake++; if (b.vx * b.vx + b.vy * b.vy > SLEEP_LIN * SLEEP_LIN || Math.abs(b.w) > SLEEP_ANG) moving++; }
+    if (Math.abs(b.x - b.x0) > 0.05 || Math.abs(b.y - b.y0) > 0.05 || Math.abs(b.a) > 0.05) displaced++;
+  }
+  $('tMoving').textContent = moving;
+  $('tTotal').textContent = world.bricks.length;
+  $('tDisplaced').textContent = fmt(100 * displaced / world.bricks.length, 0);
+  $('tImpact').textContent = impacted ? `${fmt(impactSpeed, 1)} m/s @ ${fmt(impactTime, 2)} s` : '–';
+  $('tDecel').textContent = impacted ? `${fmt(peakDecelG, 1)} g` : '–';
+  const ke = 0.5 * car.mass * (car.vx * car.vx + car.vy * car.vy);
+  $('tKE').textContent = state === 'ready' ? `${fmt(initialKE / 1000, 0)} kJ planned` : `${fmt(ke / 1000, 1)} kJ`;
+  $('energyBar').style.width = `${initialKE > 0 ? Math.min(100, 100 * ke / initialKE) : 0}%`;
+  let contacts = 0; for (const a of world.activeArbs) contacts += a.n;
+  $('tSolver').textContent = `${Math.round(1 / stepH)} Hz · ${world.iterations} it · ${world.bodies.length} bodies · ${contacts} contacts · ${awake} awake · ${fmt(fps, 0)} fps`;
+
+  const pill = $('statePill'), txt = $('stateText');
+  pill.className = 'pill' + (state === 'running' ? ' running' : state === 'settled' ? ' settled' : '');
+  if (state === 'ready') { pill.textContent = 'Ready'; txt.textContent = 'Press Test to launch the car.'; }
+  else if (state === 'settled') { pill.textContent = 'Settled'; txt.textContent = `Debris at rest after ${fmt(settledAt, 2)} s. Run again or change settings.`; }
+  else { pill.textContent = impacted ? 'Impact' : driving ? 'Launching' : 'Coasting'; txt.textContent = impacted ? 'Momentum transferred into the wall, waiting for debris to settle…' : driving ? 'Sled-assisted acceleration toward the wall.' : 'Target speed reached, coasting into the wall.'; }
+}
+
+/* =====================================================================
+   Main loop
+   ===================================================================== */
+let lastT = performance.now();
+function frame(now) {
+  let dt = (now - lastT) / 1000; lastT = now;
+  if (dt > 0.1) dt = 0.1;
+  fpsAcc += dt; fpsN++; if (fpsAcc > 0.5) { fps = fpsN / fpsAcc; fpsAcc = 0; fpsN = 0; }
+
+  if (state === 'running') {
+    accumulator += dt;
+    let steps = 0;
+    while (accumulator >= stepH && steps < maxStepsPerFrame && state === 'running') { simStep(stepH); accumulator -= stepH; steps++; }
+    if (steps >= maxStepsPerFrame) accumulator = 0;
+  }
+  updateCamera(dt);
+  updateParticles(dt);
+  render();
+  updateHud();
+  requestAnimationFrame(frame);
+}
+
+/* =====================================================================
+   Boot
+   ===================================================================== */
+buildControls();
+resize();
+resetScene();
+window.addEventListener('resize', resize);
+$('btnTest').addEventListener('click', startTest);
+$('btnReset').addEventListener('click', resetScene);
+$('btnSettings').addEventListener('click', () => $('panel').classList.toggle('collapsed'));
+$('btnDefaults').addEventListener('click', () => { Object.assign(settings, DEFAULTS); syncControls(); onSettingsChanged(); });
+window.addEventListener('keydown', e => {
+  if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA')) return;
+  if (e.code === 'Space') { e.preventDefault(); startTest(); }
+  else if (e.key === 'r' || e.key === 'R') resetScene();
+});
+requestAnimationFrame(frame);
+})();
+</script>
+</body>
+</html>

