let dvx = b.vx - b.w * r2y - a.vx + a.w * r1y;
let dvy = b.vy + b.w * r2x - a.vy - a.w * r1x;
const vn = dvx * nx + dvy * ny;
let dPn = c.massNormal * (-vn + c.velBias);
const Pn0 = c.Pn;
c.Pn = Math.max(Pn0 + dPn, 0);
dPn = c.Pn - Pn0;
let Px = dPn * nx, Py = dPn * ny;
a.vx -= im1 * Px; a.vy -= im1 * Py; a.w -= iI1 * (r1x * Py - r1y * Px);
b.vx += im2 * Px; b.vy += im2 * Py; b.w += iI2 * (r2x * Py - r2y * Px);

// position correction through pseudo velocities so it never injects kinetic energy
if (c.bias > 0 || c.Pnb > 0) {
  const bvn = (b.bvx - b.bw * r2y - a.bvx + a.bw * r1y) * nx + (b.bvy + b.bw * r2x - a.bvy - a.bw * r1x) * ny;
  let dPnb = c.massNormal * (-bvn + c.bias);
  const Pnb0 = c.Pnb;
  c.Pnb = Math.max(Pnb0 + dPnb, 0);
  dPnb = c.Pnb - Pnb0;
  const Bx = dPnb * nx, By = dPnb * ny;
  a.bvx -= im1 * Bx; a.bvy -= im1 * By; a.bw -= iI1 * (r1x * By - r1y * Bx);
  b.bvx += im2 * Bx; b.bvy += im2 * By; b.bw += iI2 * (r2x * By - r2y * Bx);
}

