primeContacts() { this.collectPairs(); this.updateContacts(false); }

// Bodies only fall asleep as whole contact islands, so a resting stack never loses the weight
// of a neighbour that dozed off on its own.
sleepIslands() {
  const bodies = this.bodies, stamp = this.stamp, stack = this.islandStack, comp = this.islandComp;
  for (let i = 0; i < bodies.length; i++) {
    const root = bodies[i];
    if (root.inactive || root.visit === stamp) continue;
    stack.length = 0; comp.length = 0; stack.push(root);
    let quiet = true;
    while (stack.length) {
      const x = stack.pop();
      if (x.visit === stamp) continue;
      x.visit = stamp; comp.push(x);
      if (!x.canSleep || x.sleepTime < SLEEP_TIME) quiet = false;
      for (const arb of x.touching) { const o = arb.a === x ? arb.b : arb.a; if (!o.inactive && o.visit !== stamp) stack.push(o); }
    }
    if (quiet) for (const x of comp) { x.asleep = true; x.vx = 0; x.vy = 0; x.w = 0; }
  }
}

forceSleepAll() {
  for (const b of this.bodies) if (!b.isStatic && b.kind === 'brick') { b.asleep = true; b.vx = 0; b.vy = 0; b.w = 0; b.sleepTime = SLEEP_TIME; }
}

