stackTest(seconds = 3, presettle = PRESETTLE_STEPS, split = SPLIT_IMPULSE, pen = ALLOWED_PENETRATION, bias = BIAS_FACTOR, iters = 10, hz = 120) {
  const keep = PRESETTLE_STEPS; PRESETTLE_STEPS = presettle; SPLIT_IMPULSE = split; ALLOWED_PENETRATION = pen; BIAS_FACTOR = bias;
  World.prototype.__iters = iters;
  const s = buildScene(settings); PRESETTLE_STEPS = keep; const w = s.world; s.car.x = -50; s.car.updateTransform();
  for (const b of w.bricks) { b.asleep = false; b.sleepTime = 0; b.canSleep = false; }
