function mulberry32(seed) {
  let a = seed >>> 0;
  return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
}

let viewScale = DEFAULTS.scale;
function panelReserve() { const p = $('panel'); return W > 900 && !p.classList.contains('collapsed') ? p.offsetWidth + 34 : 0; }
function groundScreenY() { return Math.min(Math.round(H * 0.74), H - $('hud').offsetHeight - 52); }
function usableWidthPx() { return Math.max(320, W - panelReserve()); }
function restCameraX() { return scene.car.x - scene.car.hw - 0.8; }
function restSpanMeters() { return (scene.wallW + 0.8) - restCameraX(); }
// Physics always runs at the configured px/m; the view only zooms out (down to 60%) when the
// whole rest scene cannot fit next to the settings panel.
function computeViewScale() {
  const want = scene.params.scale;
  const fit = usableWidthPx() / restSpanMeters();
  viewScale = Math.min(want, Math.max(0.6 * want, fit));
}

function resetScene() {
  scene = buildScene(settings);
  state = 'ready'; simTime = 0; accumulator = 0;
  driving = false; impacted = false; impactTime = 0; impactSpeed = 0; peakDecelG = 0; settledAt = 0;
  prevCarVx = 0; initialKE = 0.5 * settings.carMass * settings.carSpeed * settings.carSpeed;
